mapper.select:
select id, instance_key, device_id, device_name, device_status, device_model, manufacturer, device_ip, device_port, enabled, org_id, org_name, create_time, update_time from video_platform_device
instance_key = #{instanceKey}
and tenant_id = #{tenantId}
and (device_name like concat('%', #{keyword}, '%') or device_id like concat('%', #{keyword}, '%'))
and device_status = #{status}
and org_id = #{orgId}
and enabled = #{enabled}
order by create_time desc
